INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D10-TR-190', 'A mulher deve aparecer como protagonista porque é ela quem faz a travessia do aperto para o controle possível.', 'mulheres beneficiárias', 'dinheiro no bolso', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '36'), ('D10-TR-191', 'As políticas públicas entram como competências e ferramentas que ampliam o poder fazer dessa mulher.', 'mulheres beneficiárias', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '36'), ('D10-TR-192', 'O território "o mês na mão dela" se organiza pela passagem do dinheiro que some para o dinheiro que ajuda a organizar prioridades.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36'), ('D10-TR-193', 'A promessa comunicacional desse território é que, com o apoio certo, a mulher consegue decidir melhor o que pagar, comprar e reservar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36'), ('D10-TR-194', 'O território "cada real vira cuidado" se organiza pelo dinheiro que ganha valor ao se transformar em comida, gás, remédio, escola, roupa e proteção dos filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36'), ('D10-TR-195', 'A promessa comunicacional desse território é que o benefício fortalece quem sabe transformar pouco em sustentação da casa.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '36'), ('D10-TR-196', 'O território "respiro sem ilusão de fartura" se organiza por um alívio realista, que não resolve tudo, mas reduz o sufoco e abre alguma margem.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36'), ('D10-TR-197', 'A promessa comunicacional desse território é que não se trata de luxo nem de sobra, e sim da chance de respirar, quitar algo e planejar o próximo passo.', 'mulheres beneficiárias', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '36'), ('D10-TR-198', 'O território "beneficiária não é suspeita, é gestora" se organiza pelo enfrentamento da disputa moral sobre merecimento com a imagem da mulher que trabalha, cuida e prioriza.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'funciona', NULL, NULL, '36'), ('D10-TR-199', 'A promessa comunicacional desse território é que quem recebe sabe o peso de cada escolha e usa o benefício com responsabilidade.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'funciona', NULL, NULL, '36'), ('D10-TR-200', 'O território "acesso simples também é dinheiro no bolso" se organiza pela constatação de que burocracia, aplicativo instável, fila e confusão de regra consomem tempo, energia e recursos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '36'), ('D11-TR-003', 'A ideia de melhora só convence quando aparece de forma concreta no mercado, nas contas, nos filhos e na saúde.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '8'), ('D11-TR-044', 'A ideia de dinheiro no bolso precisa ser aterrada em despesas concretas: comunicação que fala de melhora sem nomear mercado, gás, luz, comida, remédio e filhos perde aderência à forma como a vida é medida.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '14'), ('D11-TR-057', 'A narrativa sobre o programa precisa partir da função de previsibilidade e tratá-lo não como dinheiro a mais, mas como base que ajuda a impedir que a casa desmonte.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '16'), ('D11-TR-069', 'A comunicação ganha força quando mostra usos concretos do benefício, em vez de falar da política apenas em termos institucionais.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '19'), ('D11-TR-091', 'Explicar o ecossistema de benefícios de forma simples pode aumentar valor percebido sem depender de propaganda.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '22'), ('D11-TR-118', 'A comunicação precisa sair do alerta e entrar na orientação: explicar o que fazer, onde resolver e quem responde por cada parte.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '26'), ('D11-TR-229', 'Ajuste principal da rota de alívio: ancorar o respiro em benefício, despesa ou situação real.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '40'), ('D11-TR-242', 'Partir de exemplos tangíveis e fáceis de reconhecer, como luz, gás, remédio, vacina e benefício de permanência escolar, facilita apreensão imediata e dá materialidade à ideia de cuidado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '42'), ('D11-TR-251', 'Manter a concretude dos exemplos e calibrar o realismo da promessa: falar em quando chega, quando funciona, onde acessar e como consultar, em vez de sugerir que tudo está garantido sempre.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '42'), ('D11-TR-252', 'Transformar a rota em peça de orientação sobre benefícios: quais existem, quem pode acessar, onde procurar e o que fazer quando não chega.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '42'), ('D11-TR-254', 'O melhor caminho é sair da afirmação de que tudo chegou e entrar na formulação de que isso existe, pode ajudar e há como acessar.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '42'), ('D11-TR-256', 'A ideia de respiro conversa com a experiência do fim do mês e com a sensação de vida pesada.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '43'), ('D11-TR-258', 'Incluir a expressão alívio no bolso melhora a peça, porque aproxima a frase da realidade financeira.', 'mulheres beneficiárias', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '43'), ('D11-TR-260', 'O alívio precisa ser demonstrado, não apenas declarado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '43'), ('D11-TR-263', 'Manter alívio como entrada emocional, mas ancorar em provas concretas: gás, luz, compra, remédio, escola, dívida ou transporte.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '43'), ('D11-TR-264', 'Substituir a expressão política pública boa por formulação mais cotidiana, do tipo quando a ajuda chega no que pesa no mês.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '43'), ('D11-TR-267', 'A peça é forte porque explica o cadastro único como porta de entrada para uma rede maior de benefícios.', 'mulheres beneficiárias', 'dinheiro no bolso', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '44'), ('D11-TR-317', 'Benefícios funcionam como estrutura de segurança, e a comunicação deve ser ancorada na vida real.', 'mulheres beneficiárias', 'dinheiro no bolso', 'comunicação de serviço', 'funciona', NULL, NULL, '50'), ('D11-TR-058', 'Você chega no final do mês e tem aquela certeza que o dinheiro do gás já está reservado.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'verbatim', NULL, NULL, '16'), ('D11-TR-071', 'Esse benefício aí salva a gente mesmo. Ajuda em muita coisa lá em casa. Mesmo meu benefício, eu faço feira. O dinheiro do meu trabalho eu já pago uma conta, já pago a escola da menina, as coisas pessoais da gente.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'verbatim', NULL, NULL, '19'), ('D11-TR-072', 'Com o dinheiro do Bolsa Família, eu pago o plano de saúde dos meus dois filhos.', 'mulheres beneficiárias', 'dinheiro no bolso', 'saúde e sus', 'verbatim', NULL, NULL, '19'), ('D11-TR-073', 'Eu uso o meu Bolsa Família em prol dele, em coisas para ele: sapato, roupa, cabelo, o convênio dele, que é essencial por conta do tratamento que ele faz.', 'mulheres beneficiárias', 'dinheiro no bolso', 'bolsa família e transferência de renda', 'verbatim', NULL, NULL, '19'), ('D11-TR-098', 'A atendente achava que, se tinha dinheiro para botar mega hair, ela tinha dinheiro, não precisava receber Bolsa Família. [...] É uma humilhação danada.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'verbatim', NULL, NULL, '23'), ('D11-TR-099', 'A gente não dá para sustentar várias crianças com esse dinheiro. Esse dinheiro é justamente para auxiliar, para dar uma segurança um pouco a mais do que a gente já recebe. E não é todo mundo que só fica em casa recebendo auxílio e sem fazer nada.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'verbatim', NULL, NULL, '23'), ('D11-TR-100', 'Eu não acho que seja bacana você viver de Bolsa Família, até porque não tem como. Mas ele ajuda muito muita gente que eu conheço, várias famílias que vivem em situação que, se não fosse o Bolsa, ia chegar na miséria mesmo, de passar fome.', 'mulheres beneficiárias', 'dinheiro no bolso', 'estigma do benefício', 'verbatim', NULL, NULL, '23'), ('D01-TR-034-mb', 'Para trabalhadoras CLT, a queixa número um é o tempo: escala 6x1, jornada dupla, deslocamento e falta de folga.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '18'), ('D01-TR-044-mb', 'Para CLT, a crítica recai sobre a defasagem do salário mínimo frente à inflação, com a escala 6x1 como fator que rouba tempo sem compensar financeiramente.', 'mulheres beneficiárias', 'trabalho digno', 'salário mínimo', 'achado', 'indício', NULL, '21'), ('D01-TR-070-mb', 'Para CLT, a proteção está vinculada à legislação, mas é percebida como insuficiente diante da sobrecarga real.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '28'), ('D01-TR-103-mb', 'A vida chegou cedo demais, mas eles não deixaram de ser jovens: a juventude aparece menos como fase livre e mais como identidade comprimida por responsabilidades adultas.', 'mulheres beneficiárias', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '38'), ('D01-TR-104-mb', 'A rotina não é só corrida, ela consome o espaço de experimentar a juventude: trabalho, estudo, deslocamento e casa ocupam a maior parte da rotina, e o tempo livre aparece menos como lazer e mais como recuperação física e mental.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '38'), ('D03-TR-010-mb', 'Carreira, trabalho e sustento é citado por 6,1% como opção mais importante na vida hoje e por 17,9% somando primeira e segunda opções.', 'mulheres beneficiárias', 'trabalho digno', 'renda e sustento', 'achado', 'indício', NULL, '16'), ('D03-TR-081-mb', 'O fim da escala 6 por 1 é conhecido por 67,3%, com avaliação de 59,3% ótima ou boa e 18,8% ruim ou péssima.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '76'), ('D11-TR-025', 'Trabalhar em casa ou ter horário flexível não elimina a sobrecarga: home office, trabalho autônomo e cuidado dentro de casa aumentam a sensação de disponibilidade permanente, sem fronteira clara entre trabalho produtivo e doméstico.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '12'), ('D11-TR-093', 'Entre as beneficiárias, rejeita-se a ideia de que quem recebe o benefício não trabalha, não se esforça ou tem filhos para ganhar benefício.', 'mulheres beneficiárias', 'trabalho digno', 'estigma do benefício', 'achado', 'indício', NULL, '23'), ('D11-TR-094', 'A defesa é prática: o valor não sustenta uma família sozinho e, portanto, não substitui trabalho, bico, cuidado ou busca por renda.', 'mulheres beneficiárias', 'trabalho digno', 'estigma do benefício', 'achado', 'indício', NULL, '23'), ('D11-TR-110', 'O benefício combate o estigma de acomodação ao mostrar que apoia mulheres que já trabalham, cuidam e se viram.', 'mulheres beneficiárias', 'trabalho digno', 'estigma do benefício', 'achado', 'indício', NULL, '24'), ('D12-TR-006-mb', 'A narrativada proteção ao trabalhador precisa ir do "se virar sozinha" para ter condições de continuar.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '8'), ('D12-TR-007-mb', 'A transformação vai da autonomia como abandono para a autonomia como potência: já se trabalha, cuida, vende, calcula e resolve, mas falta conjunção com tempo, descanso, informação, crédito, direitos e rede de segurança.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '8'), ('D12-TR-028-mb', 'A palavra proteção é desejável, mas pouco suficiente.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, NULL), ('D12-TR-029', 'Para o regime CLT existe amparo legal, mas falta tempo e descanso.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '10'), ('D12-TR-030', 'Para o regime CLT, falta salário que acompanhe o custo de vida.', 'mulheres beneficiárias', 'trabalho digno', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D12-TR-032', 'O regime de trabalho muda o estado de falta: CLT precisa recuperar tempo e dignidade, enquanto MEI e informais precisam reduzir risco e não depender só do improviso.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '10'), ('D12-TR-033-mb', 'Resolver sozinha gera orgulho, mas também naturaliza abandono institucional.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '10'), ('D12-TR-034-mb', 'Nas redes, o trabalho aparece entre orgulho e perrengue: coragem, liberdade possível, dupla jornada, crédito difícil, dúvidas sobre direitos e saúde mental.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '10'), ('D12-TR-036-mb', 'Na escuta digital, trabalhadoras em escala 6x1 falam de maternidade, deslocamento, desgaste e falta de tempo.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '10'), ('D12-TR-037-mb', 'As redes funcionam como apoio prático e emocional: ensina-se, pergunta-se e compartilha-se para tentar suprir a falta de orientação oficial.', 'mulheres beneficiárias', 'trabalho digno', 'rede de apoio', 'achado', 'indício', NULL, '10'), ('D12-TR-044-mb', 'Isotopia de esforço e autonomia: o trabalho dá orgulho e identidade, mas nasce da necessidade de se virar.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-045-mb', 'Isotopia de sobrecarga e desamparo: a falta de proteção e de condições aparece no corpo, no tempo e no medo do imprevisto.', 'mulheres beneficiárias', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-047-mb', 'Trabalhar, empreender e buscar renda aparecem como coragem, responsabilidade e tentativa de independência.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-048', 'Para o regime CLT, a jornada consome a vida.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-063-mb', 'A tensão central não está entre mulher protegida e desprotegida, mas entre autonomia como abandono e autonomia como potência.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-064-mb', 'A autonomia opera em estado de falta: há trabalho, cuidado, venda, cálculo, aprendizado e resolução de problemas, mas sem tempo, descanso, previsibilidade, informação suficiente ou rede de proteção.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-065-mb', 'O objeto de valor são condições para continuar: tempo próprio, descanso, renda mais previsível, orientação clara, crédito acessível, direitos compreendidos, proteção no imprevisto e possibilidade de planejar.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-066-mb', 'No estado final, o protagonismo se mantém sem a necessidade de sustentar tudo sozinha: trabalho com menos improviso, cuidado sem anulação, acesso a direitos e recuperação de margem.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-067-mb', 'O trabalho, o corre e a capacidade de se virar são valorizados, mas essa autonomia perde potência quando precisa substituir a proteção institucional.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-068-mb', 'O ponto de partida é um estado de falta, disjunto das condições que tornam o trabalho sustentável.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-070-mb', 'A transformação em jogo vai do "se virar sozinha" para ter condições de continuar.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-072-mb', 'A mulher aparece como sujeito competente que trabalha, cuida, resolve e sustenta, mas não deveria carregar tudo sozinha.', 'mulheres beneficiárias', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '15'), ('D12-TR-074-mb', 'O corre é vivido como obrigação solitária.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '15'), ('D12-TR-076-mb', 'No estado final, o corre deixa de ser só sobrevivência e pode virar caminho de futuro.', 'mulheres beneficiárias', 'trabalho digno', 'futuro possível', 'achado', 'indício', NULL, '15'), ('D12-TR-077-mb', 'Direito pouco entendido não protege: a proteção começa quando a informação vira caminho acessível.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-078-mb', 'A mulher aparece como sujeito que busca, aprende, compara e decide, mas precisa de clareza para agir.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-080-mb', 'O direito existe, mas parece distante, confuso ou inacessível.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '16'), ('D12-TR-082-mb', 'No estado final, torna-se possível acessar, cobrar, planejar e decidir com mais segurança.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-083', 'Para o regime CLT, proteção significa recuperar tempo, descanso e dignidade diante da escala, do deslocamento e da dupla jornada.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-084-mb', 'A trabalhadora sustenta a casa, mas também precisa de tempo próprio e de saúde mental preservada.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-086-mb', 'O trabalho consome tempo, corpo e vida familiar.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-088-mb', 'No estado final, trabalhar deixa de significar se anular e passa a permitir alguma qualidade de vida.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-092-mb', 'A autonomia depende do improviso e vira medo quando algo sai do controle.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-094-mb', 'No estado final, a autonomia se mantém com mais segurança para trabalhar, cuidar e planejar.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-254-mb', 'O sujeito desta análise não parte da passividade, mas da sobrecarga: já trabalha, cuida, compara, calcula e decide.', 'mulheres beneficiárias', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '42'), ('D12-TR-255-mb', 'O que falta é a conjunção com condições que tornem essa competência menos solitária e mais potente.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '42'), ('D13-TR-029-mb', 'A ausência de rede de apoio levou parte do público a deixar o vínculo formal para empreender por conta própria, mesmo sem clareza sobre como se organizaria.', 'mulheres beneficiárias', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-041-mb', 'Tanto o vínculo formal quanto o negócio próprio exigem muito esforço, mas cobram preços diferentes.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-042-mb', 'Entre os participantes deste estudo com vínculo formal, a queixa principal é a falta de tempo, com escala 6x1, jornada dupla, deslocamento e ausência de folga aparecendo em quase todos os relatos espontâneos sobre rotina.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, NULL), ('D13-TR-043-mb', 'No regime formal há um pouco mais de segurança, mas não absoluta.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-045-mb', 'Há uma régua específica para avaliar propostas políticas: elas são úteis quando poupam tempo e aumentam o salário, no regime formal, ou quando reduzem risco financeiro, no trabalho por conta própria.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-046', 'O cansaço tem duas causas distintas: excesso de jornada, para quem tem carteira assinada, e ansiedade sobre o futuro, para quem é autônoma.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, NULL), ('D13-TR-053-mb', 'A transição de uma mentalidade de vínculo formal para o trabalho por conta própria exige tempo, preparo, dedicação e acesso à informação, fatores nem sempre disponíveis.', 'mulheres beneficiárias', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-055-mb', 'Esses temas respondem ao principal medo de deixar o vínculo formal: perder segurança diante de um imprevisto ou ficar desprotegida no futuro.', 'mulheres beneficiárias', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-113-mb', 'A ideia de proteção do trabalhador é pouco clara e distante da realidade experimentada pelos dois regimes de trabalho.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-114-mb', 'Entre microempreendedoras há desinformação e incerteza quanto ao futuro; entre quem tem vínculo formal há exaustão e falta de proteção mesmo em ambientes institucionais.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-153-mb', 'Para quem tem vínculo formal, a proteção está vinculada à legislação, mas é percebida como insuficiente diante da sobrecarga real.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-342-mb', 'Entre os participantes deste estudo com vínculo formal, o fim da escala 6x1 é o estímulo mais forte, com apoio quase unânime e abertura para sonhar.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, NULL), ('D01-TR-035-mb', 'Há mais segurança formal no vínculo CLT, mas ela não é suficiente diante do custo de vida.', 'mulheres beneficiárias', 'trabalho digno', 'custo de vida', 'afasta', NULL, NULL, '18'), ('D13-TR-047-mb', 'Uma mensagem genérica sobre sobrecarga não fala de forma específica com nenhum dos dois regimes de trabalho.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'afasta', NULL, NULL, NULL), ('D13-TR-290-mb', 'O fechamento que condiciona o voto à escuta do público é contestado por quem lembra que o regime formal também paga por proteção equivalente, não sendo lido como diferencial de um governo específico.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'afasta', NULL, NULL, NULL), ('D12-TR-009-mb', 'O corre merece suporte, não romantização é um dos territórios de comunicação da proteção ao trabalhador.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'contexto', NULL, NULL, '8'), ('D12-TR-010-mb', 'O direito explicado vira poder de agir é um dos territórios de comunicação da proteção ao trabalhador.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'contexto', NULL, NULL, NULL), ('D12-TR-046-mb', 'Isotopia de acesso e futuro possível: proteção só ganha valor quando vira caminho claro para continuar.', 'mulheres beneficiárias', 'trabalho digno', 'futuro possível', 'contexto', NULL, NULL, '12'), ('D01-TR-036', 'Só há sensação de melhoria quando algo poupa tempo e aumenta o salário de verdade.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '18'), ('D12-TR-008', 'A proteção precisa sair do abstrato e aparecer como condição concreta para trabalhar sem se anular: orientar, explicar direitos, reduzir riscos, garantir descanso e criar suporte para CLT, MEI e informais.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '8'), ('D12-TR-027-mb', 'Mais do que proteger o trabalho, a narrativa precisa criar condições para trabalhar sem perder a vida.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '10'), ('D12-TR-038-mb', 'Proteção deve ser usada como ponto de partida, mas traduzida em condições concretas: tempo, descanso, renda, informação, crédito, direitos acessíveis e apoio.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '10'), ('D12-TR-039-mb', 'A narrativa deve falar menos de proteção em abstrato e mais de condição para trabalhar, cuidar, descansar, acessar direitos e planejar.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '10'), ('D12-TR-040-mb', 'A mulher deve aparecer como sujeito competente, mas não como alguém que precisa se virar sem apoio.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '10'), ('D12-TR-041-mb', 'A política pública entra como adjuvante do poder fazer.', 'mulheres beneficiárias', 'trabalho digno', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '10'), ('D12-TR-042-mb', 'A macronarrativa pode manter "proteção" como nome, mas precisa deslocar seu sentido para condição de possibilidade: trabalhar sem adoecer, cuidar sem se anular, empreender sem ficar desamparada e planejar sem depender só do improviso.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '11'), ('D12-TR-043-mb', 'O papel da comunicação é mostrar que proteção não é promessa abstrata, e sim passagem para condições mais concretas de acesso, continuidade e futuro.', 'mulheres beneficiárias', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '12'), ('D12-TR-050-mb', 'Direitos, informação, crédito, fiscalização e políticas públicas precisam funcionar como competências para trabalhar melhor, cuidar, descansar e planejar.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'funciona', NULL, NULL, '12'), ('D12-TR-052-mb', 'As figuras que materializam o trabalho assalariado incluem escala 6x1, hora extra, ônibus, deslocamento, filho, casa, cansaço, saúde mental, mês bom e mês ruim, licença-maternidade e auxílio-doença.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '12'), ('D12-TR-053-mb', 'As figuras que materializam a busca por acesso incluem Google, contador, cartilha, grupos, redes sociais, passo a passo, contribuição, aposentadoria, crédito, folga, renda previsível e tempo com os filhos.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'funciona', NULL, NULL, '12'), ('D12-TR-055-mb', 'Reconhecer o corre é criar condições para que ele gere futuro, não apenas exaustão.', 'mulheres beneficiárias', 'trabalho digno', 'futuro possível', 'funciona', NULL, NULL, '13'), ('D12-TR-057-mb', 'Quando a informação chega clara, torna-se possível decidir, acessar, cobrar e planejar melhor.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'funciona', NULL, NULL, '13'), ('D12-TR-059-mb', 'Trabalhar não precisa significar perder a própria vida: tempo, descanso e dignidade também são direitos.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '13'), ('D12-TR-062-mb', 'A proteção ao trabalhador deve transformar autonomia solitária em autonomia com suporte.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '13'), ('D12-TR-069-mb', 'A comunicação deve operar a transformação apresentando políticas públicas, direitos, informação, crédito e fiscalização como adjuvantes que ampliam o poder fazer e abrem espaço para um poder ser mais reconhecido.', 'mulheres beneficiárias', 'trabalho digno', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '14'), ('D12-TR-071-mb', 'Trabalho, esforço e coragem devem ser reconhecidos sem transformar sobrecarga em virtude.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '15'), ('D12-TR-073-mb', 'Valorizar o esforço com empatia, sem tratar a "mulher guerreira" como destino, e mostrar suporte concreto.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '15'), ('D12-TR-079-mb', 'Explicar regra, acesso, documentação, carência, canal e benefício em linguagem simples.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'funciona', NULL, NULL, '16'), ('D12-TR-081-mb', 'Informação clara transforma política pública em competência prática.', 'mulheres beneficiárias', 'trabalho digno', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '16'), ('D12-TR-085-mb', 'Falar de jornada, folga, deslocamento, cansaço, filhos e descanso como direitos concretos.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '17'), ('D12-TR-087-mb', 'A proteção reorganiza a relação entre trabalho, descanso e cuidado.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '17'), ('D12-TR-091-mb', 'Explicar contribuição, licença-maternidade, auxílio, aposentadoria, crédito e orientação prática.', 'mulheres beneficiárias', 'trabalho digno', 'aposentadoria e previdência', 'funciona', NULL, NULL, '18'), ('D12-TR-093-mb', 'Direitos, crédito, informação e rede entram como adjuvantes.', 'mulheres beneficiárias', 'trabalho digno', 'autonomia e amparo', 'funciona', NULL, NULL, '18'), ('D12-TR-250-mb', 'Reconhecer o "se virar" sem romantizar: há trabalho, cuidado, venda, cálculo, pesquisa e resolução de problemas, mas a mulher não pode aparecer como alguém que deve aguentar tudo sozinha.', 'mulheres beneficiárias', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '42'), ('D12-TR-251-mb', 'Transformar informação em condição de acesso: direito, benefício, crédito, voto e política pública precisam aparecer com regra clara, caminho possível e efeito concreto na rotina.', 'mulheres beneficiárias', 'trabalho digno', 'informação sobre direitos', 'funciona', NULL, NULL, '42'), ('D13-TR-288-mb', 'Os benefícios previdenciários citados, como salário-maternidade, auxílio-doença e aposentadoria, tocam preocupações reais de quem migra do vínculo formal ou já é microempreendedora e conhece pouco seus direitos.', 'mulheres beneficiárias', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, NULL), ('D11-TR-033', 'É corrido, porque mesmo trabalhando em casa, eu não vejo descanso. Talvez eu acho que se eu trabalhasse fora seria até menos trabalho do que dentro de casa o tempo todo.', 'mulheres beneficiárias', 'trabalho digno', 'jornada de trabalho', 'verbatim', NULL, NULL, '12'), ('D01-TR-026', 'Há vivência simultânea de falta de tempo, dinheiro, energia e apoio, que não se reduz a questão de renda. A maternidade organiza a rotina e produz carga mental constante e sensação de dívida consigo, com os filhos e com a casa.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '17'), ('D01-TR-028-mb', 'As políticas públicas fazem parte do dia a dia sem serem necessariamente lembradas de forma espontânea; a percepção dos benefícios é muitas vezes escassa ou pouco associada a um governo ou período específico.', 'mulheres beneficiárias', 'família e cuidado', 'atribuição de políticas públicas', 'achado', 'indício', NULL, '17'), ('D01-TR-041-mb', 'A falta de rede de apoio é apontada como marca comum dos perfis de mulheres.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D01-TR-053-mb', 'Segurança pública é problema concreto na vida da mulher.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '23'), ('D01-TR-055-mb', 'A família e cuidado é entendida como conjunto multifacetado: segurança física (ruas, escola, creche), segurança digital (crianças e redes sociais), acesso a saúde e educação, e estabilidade financeira.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '24'), ('D01-TR-056-mb', 'Entre os participantes deste estudo, o medo da violência é universal, visceral e transversal, mas nenhuma resposta institucional convence.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'forte', NULL, '25'), ('D01-TR-058-mb', 'Medida protetiva e Delegacia da Mulher são termos conhecidos, mas a desconfiança na eficácia real permanece.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '25'), ('D01-TR-059-mb', 'O pacto contra o feminicídio é praticamente desconhecido; falar dele soa institucional demais, distante do que essas mulheres vivem.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '25'), ('D03-TR-007-mb', 'Família é a opção mais citada como mais importante na vida hoje: 57,2% em primeira opção e 80,3% somando primeira e segunda opções.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '16'), ('D03-TR-008-mb', 'Saúde e bem-estar é a segunda opção mais citada como mais importante na vida hoje: 22,5% em primeira opção e 55,9% somando primeira e segunda opções.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '16'), ('D03-TR-009-mb', 'Fé e religiosidade aparece como terceira opção mais importante na vida hoje: 11,2% em primeira opção e 30,4% somando primeira e segunda opções.', 'mulheres beneficiárias', 'família e cuidado', 'fé e religiosidade', 'achado', 'indício', NULL, '16'), ('D03-TR-011-mb', 'Tempo livre e viagens é citado por 1,4% como opção mais importante na vida hoje e por 5,7% somando primeira e segunda opções.', 'mulheres beneficiárias', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-012-mb', 'Esporte, cultura e lazer é citado por 1,3% como opção mais importante na vida hoje e por 4,6% somando primeira e segunda opções.', 'mulheres beneficiárias', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-069-mb', 'A educação pública na gestão federal recebe 27,7% de avaliação ótima ou boa e 33,0% ruim ou péssima.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '73'), ('D03-TR-072-mb', 'A saúde pública na gestão federal recebe 21,5% de avaliação ótima ou boa e 44,5% ruim ou péssima, com apenas 1,4% sem saber avaliar.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '73'), ('D03-TR-073-mb', 'A segurança pública na gestão federal recebe 21,3% de avaliação ótima ou boa e 40,2% ruim ou péssima.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '73'), ('D03-TR-076-mb', 'O Minha Casa, Minha Vida Classe Média é o programa federal mais conhecido (82,8%) e o de melhor avaliação da lista: 70,1% ótima ou boa e 9,0% ruim ou péssima.', 'mulheres beneficiárias', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '76'), ('D03-TR-077-mb', 'O Pé-de-Meia, com 200 reais por aluno, é conhecido por 81,0%; a avaliação é 64,4% ótima ou boa e 17,5% ruim ou péssima.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '76'), ('D07-TR-003-mb', 'Educação pública figura entre as três áreas de maior peso na avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '3'), ('D07-TR-004-mb', 'Incentivo ao esporte, cultura e lazer tem peso muito baixo na formação da avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '3'), ('D07-TR-006-mb', 'Segurança pública situa-se em faixa alta de peso na avaliação pública de desempenho governamental, em patamar próximo ao de educação.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '3'), ('D07-TR-007-mb', 'Saúde pública, ainda que serviço de uso cotidiano, pesa menos na avaliação de desempenho governamental do que temas de percepção difusa como custo de vida e posição do país no exterior.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '3'), ('D07-TR-008-mb', 'Programas sociais de modo geral ocupam faixa intermediária de peso na avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'família e cuidado', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '3'), ('D07-TR-009-mb', 'Programas de habitação e moradia ocupam faixa intermediária de peso na avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '3'), ('D07-TR-010-mb', 'Combate às desigualdades e privilégios tem peso baixo na formação da avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'família e cuidado', 'desigualdade', 'achado', 'indício', NULL, '3'), ('D07-TR-022-mb', 'Custo de vida, poder de compra e economia consta na lista de temas cuja menção deve ser evitada no momento.', 'mulheres beneficiárias', 'família e cuidado', 'custo de vida', 'achado', 'indício', NULL, '5'), ('D07-TR-023-mb', 'Segurança pública consta na lista de temas cuja menção deve ser evitada no momento.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '5'), ('D07-TR-025-mb', 'Educação pública consta na lista de temas cuja menção deve ser evitada no momento.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '5'), ('D07-TR-026-mb', 'Saúde pública consta na lista de temas cuja menção deve ser evitada no momento.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '5'), ('D07-TR-029-mb', 'Na Região Sul, segurança pública ocupa posição de peso mais alta na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '6'), ('D07-TR-030-mb', 'Na Região Sul, saúde pública ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '6'), ('D07-TR-033-mb', 'Na Região Sudeste, saúde pública e programas sociais ocupam posição de peso mais alta na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '7'), ('D07-TR-036-mb', 'Na Região Centro-Oeste, saúde pública é a segunda área de maior peso na avaliação de desempenho governamental, posição muito acima da que ocupa no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '8'), ('D07-TR-040-mb', 'Na Região Nordeste, educação pública é a área de maior peso na avaliação de desempenho governamental, à frente de custo de vida.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '9'), ('D07-TR-041-mb', 'Na Região Nordeste, programas de habitação e moradia ocupam a quarta posição em peso na avaliação, com participação quase o dobro da observada no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '9'), ('D07-TR-046-mb', 'Na Região Norte, segurança pública ocupa posição de peso mais alta na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '10'), ('D07-TR-047-mb', 'Na Região Norte, saúde pública ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '10'), ('D10-TR-004', 'Na macronarrativa de proteção da família, a narrativa central vai da ameaça à vida protegida e aberta ao futuro.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-005', 'A transformação semiótica da proteção da família parte da experiência disfórica da vulnerabilidade para a experiência eufórica de uma vida mais segura, em que proteção, previsibilidade e cuidado efetivo permitem respirar, planejar e sonhar.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '8'), ('D10-TR-029', 'A proteção é medida na rotina: comida, gás, luz, remédio, escola, segurança, benefício que cai na data e regra clara.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '10'), ('D10-TR-030', 'O cuidado só é reconhecido quando reduz a carga de quem sustenta a casa, o que vai muito além da dimensão financeira.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '10'), ('D10-TR-031', 'A mulher aparece como quem organiza, antecipa riscos, administra o orçamento e transforma políticas públicas em proteção real para os filhos.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '10'), ('D10-TR-032', 'Na conversa digital, a proteção se amplia para a defesa da vida, abrangendo feminicídio, crianças nas telas, mães atípicas, saúde mental, BPC/LOAS, CRAS e falhas no atendimento na ponta.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '10'), ('D10-TR-033', 'Nas redes, mulheres aparecem buscando informação, denunciando falhas, formando redes de apoio e expressando medo, desamparo, cansaço e desejo de segurança.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'achado', 'indício', NULL, '10'), ('D10-TR-036', 'A proteção da família se organiza em narrativas mais eufóricas ou disfóricas, oscilando entre a contenção do risco e a possibilidade de futuro.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '11'), ('D10-TR-037', 'Vida, proteção, segurança e direito de sonhar estruturam a dimensão eufórica da narrativa de proteção da família.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '11'), ('D10-TR-038', 'Proteger a família significa garantir filhos vivos, alimentados, seguros, estudando e com possibilidade de futuro.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '11'), ('D10-TR-039', 'A maternidade aparece como missão de sustentação e abertura de futuro: administra-se risco, orçamento e rotina, mas também se busca criar condições para respirar, planejar e sonhar além da sobrevivência.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '11'), ('D10-TR-041', 'Medo, falha, luta e desamparo estruturam a dimensão disfórica da narrativa de proteção da família.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '11'), ('D10-TR-042', 'Feminicídio, insegurança, bloqueio, fila, lei que não funciona e atendimento difícil fazem o cuidado parecer frágil e constantemente ameaçado.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '11'), ('D10-TR-043', 'A proteção aparece como sobrevivência sob pressão e contenção do pior, exigindo esforço contínuo diante de burocracia, incerteza, violência e falta de acesso a serviços e informação confiável.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '11'), ('D10-TR-046', 'Os antissujeitos do percurso narrativo da proteção são violência, bloqueio, fila, desinformação, insegurança e falhas de acesso.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'achado', 'indício', NULL, '12'), ('D10-TR-047', 'O objeto de valor do percurso narrativo da proteção é uma vida mais segura, previsível e aberta ao futuro.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '12'), ('D10-TR-048', 'Nesse percurso, a mulher é a protagonista: cuida, decide, busca direitos, aciona redes e transforma acesso em proteção concreta.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '12'), ('D10-TR-061', 'Todos os territórios partem da mesma virada narrativa: sair da mulher como beneficiária vulnerável e colocá-la como protagonista da proteção.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '13'), ('D10-TR-064', 'O papel atribuído à mulher nesse território é o de avaliadora da entrega pública: o cuidado é reconhecido como recebido quando pode ser medido no orçamento, no filho e na rotina.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '14'), ('D10-TR-066', 'A transformação narrativa desse território vai de incerteza, falha e sobrecarga na gestão da casa, pela via do acesso a serviços que funcionam e de informação clara, até previsibilidade, organização e sensação de controle sobre a vida cotidiana.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '14'), ('D10-TR-068', 'O papel atribuído à mulher nesse território é o de protagonista da proteção familiar: administra riscos, cuida dos filhos, segura a casa e busca caminhos para melhorar a vida.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '15'), ('D10-TR-070', 'A transformação narrativa desse território vai de uma vida centrada na sobrevivência e na contenção de riscos, pela via do fortalecimento das condições de cuidado e da redução da pressão cotidiana, até a abertura para planejamento, autonomia e construção de futuro.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '15'), ('D10-TR-072', 'O papel atribuído à mulher nesse território é o de cuidadora que também precisa ser cuidada: sustenta a família, mas precisa de ferramentas para não adoecer nem ficar sozinha.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '16'), ('D10-TR-074', 'A transformação narrativa desse território vai de isolamento, sobrecarga e sensação de estar sozinha, pela via do acesso a redes de apoio, serviços e informação, até compartilhamento do cuidado, alívio da carga e fortalecimento coletivo.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '16'), ('D10-TR-077', 'O papel atribuído à mulher nesse território é o de sujeito de direito e de cobrança: identifica riscos, protege, denuncia, cobra e busca segurança para si e para os filhos.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '17'), ('D10-TR-079', 'A transformação narrativa desse território vai de ameaça constante, medo e sensação de desproteção, pela via do acesso a mecanismos de proteção, denúncia e resposta institucional, até maior segurança, confiança e capacidade de agir diante dos riscos.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '17'), ('D10-TR-081', 'O papel atribuído à mulher nesse território é o de sujeito de futuro: não se trata apenas de resistir, mas de poder imaginar uma vida melhor para si e para os filhos.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '18'), ('D10-TR-083', 'A transformação narrativa desse território vai de uma vida limitada à sobrevivência e à gestão do imediato, pela via da ampliação das condições de segurança e estabilidade, até a possibilidade de sonhar, planejar e construir uma vida mais plena.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '18'), ('D11-TR-004', 'O cuidado público é avaliado pela capacidade de aliviar a carga materna: garantir comida, gás, luz, remédio, escola, segurança e menos incerteza no fim do mês.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '8'), ('D11-TR-006', 'Ameaça de bloqueio, atraso ou falha no cadastro desorganiza mais do que a perda de renda em si.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '8'), ('D11-TR-007', 'O principal gargalo não é rejeição ao programa, mas ansiedade operacional: dúvidas sobre atualização cadastral, atendimento local, aplicativo, bloqueio e canais confiáveis de informação.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '8'), ('D11-TR-018', 'Segurança, saúde e educação entram como dimensões centrais da economia emocional da casa, e limitam a sensação de melhora mesmo quando há avanço financeiro.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '11'), ('D11-TR-027', 'Consulta médica, reunião escolar, filho doente ou demanda de trabalho exigem remanejamentos imediatos, o que reforça a importância de políticas e comunicações que reduzam incerteza em vez de acrescentar burocracia.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'achado', 'indício', NULL, '12'), ('D11-TR-034', 'A maior preocupação materna não cabe só na chave da renda: proteção significa comida, segurança, saúde, escola e futuro.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '13'), ('D11-TR-035', 'Ao falar das maiores preocupações como mães, a conversa se amplia rapidamente para segurança, saúde e educação, o que indica que a vida material é inseparável da sensação de proteção dos filhos.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '13'), ('D11-TR-036', 'A segurança aparece como medo cotidiano e não como tema abstrato: filho na rua, celular no ônibus, ida à escola, parque, creche ou cuidado por terceiros acionam vigilância permanente, que limita a liberdade das crianças e aumenta a carga emocional das mães.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '13'), ('D11-TR-037', 'A saúde pesa porque o serviço público é vivido entre gratidão, espera e risco: quando consulta, exame ou diagnóstico demoram, resta aguardar, pagar particular ou conviver com a angústia, o que transforma acesso à saúde em marcador de dignidade.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '13'), ('D11-TR-038', 'A educação preocupa menos como matrícula e mais como aprendizagem real: o medo é que a criança frequente a escola sem estar sendo preparada para o futuro.', 'mulheres beneficiárias', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '13'), ('D11-TR-049', 'A segurança funciona como limite transversal da melhora: mesmo com avanço financeiro, moradia ou benefício, a piora percebida na violência impede que a vida seja sentida como plenamente melhor.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '15'), ('D11-TR-065', 'A narrativa mais promissora apresenta o programa como direito que protege a dignidade de quem já trabalha, cuida e se vira.', 'mulheres beneficiárias', 'família e cuidado', 'estigma do benefício', 'achado', 'indício', NULL, '18'), ('D11-TR-108', 'O benefício reforça que a vulnerabilidade não é falha individual, mas uma condição que exige proteção pública.', 'mulheres beneficiárias', 'família e cuidado', 'estigma do benefício', 'achado', 'indício', NULL, '24'), ('D11-TR-109', 'O benefício ajuda a deslocar a narrativa da ajuda para o campo do direito, da dignidade e da responsabilidade do Estado.', 'mulheres beneficiárias', 'família e cuidado', 'estigma do benefício', 'achado', 'indício', NULL, '24'), ('D11-TR-123', 'A regra não é vivida como burocracia neutra: quando a consequência é perder o benefício, qualquer exigência mal explicada vira ameaça.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '27'), ('D11-TR-142', 'O principal risco não é rejeição ao programa, mas a ansiedade operacional.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '30'), ('D11-TR-143', 'O medo de perder nasce da combinação entre benefício estrutural, regra pouco dominada, atendimento difícil e responsabilidade difusa.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '30'), ('D11-TR-144', 'Não basta saber que se tem direito: é preciso saber como manter o benefício, onde resolver, quem procurar e o que fazer quando algo trava.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'achado', 'indício', NULL, '30'), ('D11-TR-147', 'Cuidado, nesse território, é previsibilidade operacional: regra clara, caminho simples, fonte confiável e solução acessível.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'achado', 'indício', NULL, '30'), ('D11-TR-148', 'O benefício dá segurança quando cai certo, mas vira ansiedade quando mantê-lo depende de regras, sistemas e atendimentos que nem sempre parecem claros.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '30'), ('D11-TR-152', 'O território de governo, cuidado e previsibilidade tem alto potencial narrativo, desde que cuidado seja traduzido em segurança prática.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'achado', 'forte', NULL, '32'), ('D11-TR-153', 'No território de família, fé, dignidade e proteção, a família é o centro moral da conversa, não como discurso abstrato, mas como filho protegido, comida, saúde, escola, segurança e futuro.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'achado', 'indício', NULL, '32'), ('D11-TR-154', 'O território de família, fé, dignidade e proteção tem potencial narrativo muito alto porque conecta política pública à missão materna.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'achado', 'forte', NULL, '32'), ('D11-TR-161', 'O governo que cuida é o que reduz ansiedade operacional: faz o benefício cair certo, explica o direito, facilita acesso e não abandona quando dá problema.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'achado', 'indício', NULL, '33'), ('D11-TR-162', 'A ideia de governo que cuida não aparece como noção emocional genérica: é reconhecida quando resolve algo concreto na vida, como benefício, casa, gás, luz, saúde, escola, atendimento e segurança.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'achado', 'forte', NULL, '33'), ('D11-TR-163', 'A previsibilidade é o núcleo mais forte desse território: cuidado é saber que o benefício cai, que a regra é clara e que existe caminho para resolver.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'achado', 'forte', NULL, '33'), ('D11-TR-172', 'A família deve ser tratada como responsabilidade concreta: garantir comida, escola, saúde, segurança e futuro. É nesse ponto que dignidade vira linguagem política.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'achado', 'indício', NULL, '34'), ('D11-TR-173', 'A família é o território mais espontâneo e emocionalmente carregado, porque organiza quase todas as prioridades: filhos, comida, segurança, saúde, escola, futuro e respeito.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'achado', 'forte', NULL, '34'), ('D11-TR-174', 'A maternidade funciona como régua moral: o que importa é se a política ajuda a proteger os filhos e a criar com dignidade.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'achado', 'indício', NULL, '34'), ('D11-TR-175', 'A fé aparece como linguagem de força, esperança e sustentação, mas não substitui demanda por política pública: é possível confiar em Deus e, ao mesmo tempo, cobrar governo, escola, saúde e segurança.', 'mulheres beneficiárias', 'família e cuidado', 'fé e religiosidade', 'achado', 'indício', NULL, '34'), ('D11-TR-221', 'Benefícios concretos geram identificação, mas podem soar idealizados quando a entrega falha.', 'mulheres beneficiárias', 'família e cuidado', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '40'), ('D11-TR-225', 'Proteção digital é tema relevante e novo, mas a sigla usada precisa ser explicada.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'achado', 'indício', NULL, '40'), ('D11-TR-226', 'Há rota equilibrada que combina família, cuidado e serviços concretos com linguagem clara.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'achado', 'indício', NULL, '40'), ('D11-TR-238', 'Há rotas com bom potencial temático que precisam de tradução, entre elas a de proteção digital, tema relevante, novo e aderente à maternidade, cuja sigla não é autoexplicativa e precisa mostrar como funciona na prática.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'achado', 'indício', NULL, '41'), ('D11-TR-241', 'Benefícios concretos geram identificação, mas a mensagem perde força quando parece prometer mais do que a experiência confirma.', 'mulheres beneficiárias', 'família e cuidado', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '42'), ('D11-TR-287', 'A preocupação com o celular mobiliza as mães, mas a sigla usada para proteção digital ainda não explica o que fazer.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'achado', 'forte', NULL, '46'), ('D11-TR-320', 'O medo de bloqueio e a dificuldade de resolver no atendimento local transformam o cadastro único em zona de ansiedade.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'achado', 'indício', NULL, '50'), ('D13-TR-167-mb', 'A preocupação com segurança e educação dos filhos aparece de forma muito parecida nos dois regimes de trabalho.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'achado', 'indício', NULL, NULL), ('D01-TR-057-mb', 'A narrativa de "governo que cuida" soa paternalista: o problema percebido não é falta de cuidado, é falta de lei aplicada com rigor.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'afasta', NULL, NULL, '25'), ('D10-TR-076', 'Tratar esses riscos apenas como campanha ou fala bonita, sem resposta concreta, enfraquece a comunicação de proteção.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'afasta', NULL, NULL, '17'), ('D11-TR-016', 'Narrativas que falam de cuidado sem reconhecer a sobrecarga materna têm baixa credibilidade.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'afasta', NULL, NULL, '11'), ('D11-TR-164', 'O cuidado perde força quando vira burocracia, ameaça ou espera sem resposta, e nesses casos o governo aparece menos como proteção e mais como sistema difícil de acessar.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'afasta', NULL, NULL, '33'), ('D11-TR-177', 'O discurso político sobre família gera desconfiança quando parece moralismo, julgamento ou fala distante de quem não conhece a rotina.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'afasta', NULL, NULL, '34'), ('D11-TR-272', 'Dizer que tudo começa no cadastro único é útil, mas insuficiente sem orientar sobre atendimento, atualização, consulta e critérios.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'afasta', NULL, NULL, '44'), ('D11-TR-291', 'A sigla usada para o estatuto de proteção digital não é autoexplicativa, e muitas não sabem o que significa nem como protege na prática.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'afasta', NULL, NULL, '46'), ('D11-TR-301', 'A mensagem perde força quando parece afirmar que vacina, remédio e proteção estão sempre disponíveis.', 'mulheres beneficiárias', 'família e cuidado', 'saúde e sus', 'afasta', NULL, NULL, '47'), ('D11-TR-167', 'A narrativa deve traduzir cuidado como estabilidade cotidiana, não como promessa grandiosa.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'contexto', NULL, NULL, '33'), ('D11-TR-168', 'Cuidar é fazer funcionar sem aumentar a incerteza.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'contexto', NULL, NULL, '33'), ('D11-TR-332', 'As narrativas mais eficazes combinam acolhimento, prova concreta e caminho prático.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'contexto', NULL, NULL, '51'), ('D01-TR-054-mb', 'Cuidar é proteger a vida concreta, mas também devolver às mulheres o direito de fazer planos.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '23'), ('D01-TR-060-mb', 'Não é sobre anunciar mais uma lei, é sobre provar que alguma coisa mudou.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '25'), ('D01-TR-061-mb', 'Spray de pimenta aparece como medida prática e imediata de autodefesa, mais fácil de comunicar como ação concreta do que como promessa institucional. Ideia para teste, ainda não avaliada em campo.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '25'), ('D01-TR-064-mb', 'Reconhecer a mulher como quem já protege, não como quem recebe proteção: a política fortalece o que ela já faz, não inaugura o cuidado.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D01-TR-065-mb', 'O cuidado não pode depender só da força individual da mãe: a rede de assistência deve cuidar de quem cuida, e a imagem da "mãe heroica que dá conta de tudo sozinha" precisa ser quebrada.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D01-TR-066-mb', 'Responder à violência com caminho prático, não com campanha genérica; a proteção digital dos filhos é a porta de entrada mais aberta desse território, e feminicídio é lugar delicado de diálogo, pois não há sensação de segurança com as soluções disponíveis.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '26'), ('D01-TR-067-mb', 'Ancorar o sonho na segurança: quando o cuidado funciona, sobra espaço para estudar, descansar e sonhar, o direito de sonhar além da sobrevivência.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D10-TR-006', 'O cuidado precisa sair da promessa e aparecer como proteção concreta: resolver, orientar, acolher, responder e reduzir riscos reais.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '8'), ('D10-TR-028', 'Cuidar significa proteger a vida concreta e também devolver a essas mulheres o direito de fazer planos.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '10'), ('D10-TR-034', 'A macronarrativa deve sair do "governo que cuida" como promessa e entrar no "cuidado que permite viver melhor": resolver, orientar, proteger e abrir futuro.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '10'), ('D10-TR-035', 'O território mais forte é colocar essa mulher no centro, não como quem apenas recebe cuidado, mas como quem faz o cuidado acontecer e precisa de condições para sonhar além da sobrevivência.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '10'), ('D10-TR-040', 'Casa, filho, comida, gás, luz, remédio, escola, celular, CRAS, aplicativo e benefício funcionando são as figuras que tornam visível o cuidado que protege e permite avançar.', 'mulheres beneficiárias', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '11'), ('D10-TR-044', 'Fila, sistema fora do ar, benefício cortado, criança na tela, mãe atípica, medida protetiva e rede de mulheres tensionada são as figuras que mostram onde a promessa de cuidado falha ou é colocada à prova.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '11'), ('D10-TR-045', 'A proteção da família deve ser narrada como uma travessia entre disforia e euforia.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '12'), ('D10-TR-049', 'As políticas públicas devem aparecer como adjuvantes e competências que ampliam o poder fazer dessa mulher, e não como favor.', 'mulheres beneficiárias', 'família e cuidado', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '12'), ('D10-TR-050', 'A comunicação mais forte é a que mostra como benefício, informação, atendimento e proteção sustentam e instruem essa mulher a superar ameaças e a construir uma vida que não seja apenas sobrevivência, mas também plano, respiro e sonho.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '12'), ('D10-TR-051', 'O território "cuidado que transforma a vida real" se organiza pela comprovação da proteção na ponta: benefício, atendimento, regra clara, serviço e solução.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '13'), ('D10-TR-052', 'A promessa comunicacional desse território é que, quando o cuidado funciona, a mulher ganha segurança para organizar a casa.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '13'), ('D10-TR-053', 'O território "mãe que protege e abre futuro" se organiza pela mulher como quem sustenta a travessia entre ameaça e futuro: cuida, decide, antecipa riscos e busca caminhos.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '13'), ('D10-TR-054', 'A promessa comunicacional desse território é que a política pública fortalece quem já protege a família todos os dias.', 'mulheres beneficiárias', 'família e cuidado', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '13'), ('D10-TR-055', 'O território "rede para cuidar de quem cuida" se organiza pela constatação de que o cuidado não pode depender apenas da força individual da mãe e precisa de apoio, informação e rede.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '13'), ('D10-TR-056', 'A promessa comunicacional desse território é que quem cuida também precisa ser cuidada para não carregar tudo sozinha.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '13'), ('D10-TR-057', 'O território "defesa da vida sem promessa vazia" se organiza pelo enfrentamento de riscos concretos: violência, feminicídio, insegurança, exposição digital e falha institucional.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '13'), ('D10-TR-058', 'A promessa comunicacional desse território é que defender a vida exige orientação, acolhimento, resposta e responsabilização.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '13'), ('D10-TR-059', 'O território "direito de sonhar além da sobrevivência" se organiza pela ideia de que a proteção não termina em evitar o pior e deve abrir margem para descanso, autonomia, circulação, planos e futuro.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '13'), ('D10-TR-060', 'A promessa comunicacional desse território é que, quando a vida fica mais segura, a mulher pode voltar a desejar, planejar e sonhar.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '13'), ('D10-TR-062', 'As políticas públicas entram como competências e ferramentas que ampliam o poder de agir dessa mulher, reduzindo ameaças e criando condições para uma vida mais plena.', 'mulheres beneficiárias', 'família e cuidado', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '13'), ('D10-TR-063', 'Cuidar significa fazer funcionar: benefício, atendimento, regra clara, proteção, serviço e solução quando algo falha.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '14'), ('D10-TR-065', 'A comunicação deve mostrar provas concretas de cuidado: onde acessar, como resolver, quem responde e o que muda na vida prática.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '14'), ('D10-TR-067', 'Proteção não se reduz a evitar o pior: é criar margem para que a família viva com mais segurança, descanso e possibilidade de plano.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '15'), ('D10-TR-069', 'A comunicação deve valorizar a mulher como quem faz o cuidado acontecer, conectando políticas públicas a respiro, autonomia e futuro.', 'mulheres beneficiárias', 'família e cuidado', 'cuidado e sobrecarga', 'funciona', NULL, NULL, '15'), ('D10-TR-071', 'O cuidado não pode depender apenas da força individual da mãe: exige apoio, informação, atendimento e outras mulheres.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '16'), ('D10-TR-073', 'A comunicação deve apresentar políticas, canais e redes como competências disponíveis: benefício, CRAS, CadÚnico, BPC/LOAS, saúde, escola e rede comunitária.', 'mulheres beneficiárias', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '16'), ('D10-TR-075', 'Violência contra mulheres, insegurança e exposição das crianças exigem respostas concretas.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '17'), ('D10-TR-078', 'A proteção deve ser comunicada com consequência prática: orientação, denúncia, acolhimento, encaminhamento, rapidez e responsabilização.', 'mulheres beneficiárias', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '17'), ('D10-TR-080', 'A vida plena começa quando a proteção deixa de ser apenas contenção do medo e passa a ser condição para planejar, circular e desejar.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '18'), ('D10-TR-082', 'A narrativa deve ser aspiracional e ao mesmo tempo aterrada: quando o cuidado funciona, sobra espaço para estudar, trabalhar, descansar, circular e sonhar.', 'mulheres beneficiárias', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '18'), ('D11-TR-039', 'A proteção da família não gera identificação como valor genérico: precisa se materializar em filho seguro, atendimento de saúde, escola funcionando, comida garantida e menos medo no dia a dia.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '13'), ('D11-TR-085', 'É necessário reconhecer a diferença entre sobrevivência e respiro sem hierarquizar as beneficiárias, pois ambas são formas de proteção.', 'mulheres beneficiárias', 'família e cuidado', 'estigma do benefício', 'funciona', NULL, NULL, '21'), ('D11-TR-125', 'A comunicação precisa traduzir regra em passo a passo de manutenção do benefício.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '27'), ('D11-TR-149', 'A comunicação precisa transformar medo de bloqueio em orientação de cuidado.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '30'), ('D11-TR-176', 'O discurso político sobre família gera identificação quando fala da vida real.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'funciona', NULL, NULL, '34'), ('D11-TR-178', 'A narrativa mais forte coloca a mãe como agente de proteção, não como vítima passiva.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'funciona', NULL, NULL, '34'), ('D11-TR-210', 'Família e dignidade dão calor emocional à narrativa, mas precisam ser ancoradas em proteção real: comida, escola, saúde, segurança, renda e futuro.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'funciona', NULL, NULL, '38'), ('D11-TR-230', 'O cuidado vem também do cardápio ampliado de políticas públicas: detalhar quais são os benefícios e como acessar é muito importante', 'mulheres beneficiárias', 'família e cuidado', 'bolsa família e transferência de renda', 'funciona', NULL, NULL, '40'), ('D11-TR-232', 'Ajuste principal da rota de proteção digital: traduzir a sigla e mostrar como protege na prática.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '40'), ('D11-TR-233', 'Ajuste principal da rota de cuidado no dia a dia: evitar parecer garantia total onde há falhas de acesso.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '40'), ('D11-TR-240', 'A comunicação deve tratar cuidado como entrega verificável, não como afirmação institucional: mostrar o que chega, como acessar, quem resolve e por que isso melhora a vida concreta.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '41'), ('D11-TR-244', 'A peça é lida como cuidado, acolhimento e alívio concreto.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '42'), ('D11-TR-283', 'Trocar a convocação genérica de cobrança por um passo a passo: onde reclamar, qual canal usar, como registrar protocolo e o que fazer se não houver resposta.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '45'), ('D11-TR-284', 'Explicar responsabilidades sem parecer transferência de culpa, esclarecendo que o benefício é federal, mas o atendimento do cadastro depende da gestão municipal.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'funciona', NULL, NULL, '45'), ('D11-TR-294', 'Explicar a sigla por extenso, indicando que se trata do estatuto da criança e do adolescente aplicado também à internet.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '46'), ('D11-TR-295', 'Mostrar exemplos concretos de proteção: denúncia, responsabilização de plataformas, segurança contra abuso, golpes, exposição e contato com desconhecidos.', 'mulheres beneficiárias', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '46'), ('D11-TR-304', 'Manter a ideia de cuidado no dia a dia com linguagem mais orientadora: onde buscar, como acessar e o que fazer quando falta.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '47'), ('D11-TR-323', 'Tratar cuidado como orientação prática: linguagem simples, passo a passo, fonte verificável e reconhecimento do esforço dessas mulheres.', 'mulheres beneficiárias', 'família e cuidado', 'comunicação de serviço', 'funciona', NULL, NULL, '50'), ('D11-TR-324', 'O cuidado funciona quando é traduzido em previsibilidade: benefício que cai, regra clara, atendimento que resolve e redução de incerteza.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'funciona', NULL, NULL, '51'), ('D11-TR-326', 'Família, dignidade e pertencimento são territórios fortes, mas precisam evitar moralismo ou cobrança de gratidão.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'funciona', NULL, NULL, '51'), ('D11-TR-331', 'A promessa de cuidado precisa ser verificável na experiência cotidiana.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'funciona', NULL, NULL, '51'), ('D11-TR-169', 'Eu acho que o governo que cuida é aquele que olha para quem mais precisa. Porque tem muita gente que depende desse dinheiro para comer.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'verbatim', NULL, NULL, '33'), ('D11-TR-170', 'Para mim, cuidar é quando funciona. Quando você precisa resolver alguma coisa e consegue resolver.', 'mulheres beneficiárias', 'família e cuidado', 'confiança nas instituições', 'verbatim', NULL, NULL, '33'), ('D11-TR-171', 'Não adianta falar que ajuda se a gente vai lá e não consegue atendimento. Tem que funcionar de verdade.', 'mulheres beneficiárias', 'família e cuidado', 'acesso a benefícios e atendimento', 'verbatim', NULL, NULL, '33'), ('D11-TR-180', 'A gente entrega nas mãos de Deus, mas também precisa que as coisas funcionem, porque só a fé não resolve tudo.', 'mulheres beneficiárias', 'família e cuidado', 'fé e religiosidade', 'verbatim', NULL, NULL, '34'), ('D11-TR-181', 'Eu tenho muita fé, mas também preciso de médico, escola e segurança para os meus filhos.', 'mulheres beneficiárias', 'família e cuidado', 'fé e religiosidade', 'verbatim', NULL, NULL, '34'), ('D11-TR-183', 'Família não é discurso. Família é conseguir cuidar dos filhos com dignidade.', 'mulheres beneficiárias', 'família e cuidado', 'rede de proteção social', 'verbatim', NULL, NULL, '34'), ('D01-TR-083', 'A potência do país aparece em coisas concretas (SUS, Pix, ciência, esporte, cultura), mais do que em símbolo abstrato.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '31'), ('D01-TR-084-mb', 'O vínculo mais seguro com o país nasce do cotidiano: família, comida, humor, cuidado, território, com o orgulho regional (nordestino/baiano) como camada extra de identidade.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '31'), ('D03-TR-070-mb', 'A defesa do Brasil no exterior recebe 24,8% de avaliação ótima ou boa e 34,5% ruim ou péssima, com 15,2% sem saber avaliar, a maior taxa de não avaliação entre as áreas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '73'), ('D03-TR-071-mb', 'A proteção ao meio ambiente na gestão federal recebe 23,2% de avaliação ótima ou boa e 37,8% ruim ou péssima.', 'mulheres beneficiárias', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '73'), ('D03-TR-087-mb', 'O Programa Brasil Soberano é o menos conhecido da lista (15,9%); a avaliação registrada é 35,5% ótima ou boa, 14,8% ruim ou péssima e 22,2% não sabem avaliar.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '76'), ('D07-TR-002-mb', 'A defesa do país no exterior aparece entre as três áreas de maior peso na avaliação pública de desempenho governamental, acima de áreas de serviço de uso direto.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '3'), ('D07-TR-005-mb', 'Proteção ao meio ambiente tem peso muito baixo na formação da avaliação pública de desempenho governamental.', 'mulheres beneficiárias', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '3'), ('D07-TR-024-mb', 'Defesa do Brasil no exterior consta na lista de temas cuja menção deve ser evitada no momento.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '5'), ('D07-TR-032-mb', 'Na Região Sudeste, a defesa do país no exterior é a área de maior peso na avaliação de desempenho governamental, à frente de custo de vida.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '7'), ('D07-TR-034-mb', 'Na Região Sudeste, proteção ao meio ambiente tem peso na avaliação cerca do dobro do observado no conjunto do país, ainda que em patamar baixo.', 'mulheres beneficiárias', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '7'), ('D07-TR-037-mb', 'Na Região Centro-Oeste, proteção ao meio ambiente ocupa a quarta posição em peso na avaliação, contraste marcado com a última posição no conjunto do país.', 'mulheres beneficiárias', 'brasil e pertencimento', 'clima', 'achado', 'indício', NULL, '8'), ('D07-TR-038-mb', 'Na Região Centro-Oeste, a defesa do país no exterior ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '8'), ('D07-TR-042-mb', 'Na Região Nordeste, a defesa do país no exterior ocupa posição de peso muito mais baixa na avaliação do que no conjunto do país.', 'mulheres beneficiárias', 'brasil e pertencimento', 'soberania e política externa', 'achado', 'indício', NULL, '9'), ('D12-TR-020-mb', 'A narrativa central de Brasil Core vai do desencanto com o país real ao reencantamento lúcido com um Brasil possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '8'), ('D12-TR-021-mb', 'A transformação semiótica vai da disjunção com um Brasil visto como problema, disputa ou propaganda para a conjunção com um orgulho maduro: amar o país apesar das falhas, reconhecendo nele potência coletiva, pertencimento e futuro possível.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '8'), ('D12-TR-175-mb', 'Entre os participantes deste estudo, Brasil Core é a macronarrativa mais transversal: mesmo entre descrentes, o orgulho pelo país permanece como vínculo afetivo.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '30'), ('D12-TR-176-mb', 'Nas redes, o orgulho nacional aparece como território disputado por campos políticos distintos, articulado a diplomacia, patriotismo e defesa de valores.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '30'), ('D12-TR-179-mb', 'A força das mulheres e do povo brasileiro mobiliza, mas não pode romantizar sobrecarga.', 'mulheres beneficiárias', 'brasil e pertencimento', 'gênero e trabalho', 'achado', 'indício', NULL, '30'), ('D12-TR-182-mb', 'O orgulho nacional convive com críticas a violência, serviços públicos, custo de vida e descrença institucional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '30'), ('D12-TR-183-mb', 'A escuta digital mostra um patriotismo lúcido: amar o país apesar das falhas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '30'), ('D12-TR-185-mb', 'O vínculo mais seguro com o país nasce da vida concreta: família, trabalho, cultura, comida, cuidado e orgulho regional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '30'), ('D12-TR-186-mb', 'Nas redes, o amor pelo país aparece em cenas do dia a dia, laços familiares, estados, humor e experiências compartilhadas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '30'), ('D12-TR-189-mb', 'Isotopia de país em disputa: o orgulho nacional é mobilizado por campos políticos diferentes e pode ser capturado pela polarização.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '32'), ('D12-TR-190-mb', 'Os temas associados são patriotismo, soberania, diplomacia, liderança internacional, defesa de valores e pertencimento político.', 'mulheres beneficiárias', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '32'), ('D12-TR-192-mb', 'Isotopia de potência brasileira: o país gera orgulho quando aparece como capacidade coletiva, criatividade e reconhecimento.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '32'), ('D12-TR-193-mb', 'Os temas associados são esporte, cultura, ciência, cinema, saúde pública, tecnologia nacional e reconhecimento internacional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '32'), ('D12-TR-195-mb', 'Isotopia do Brasil do cotidiano: o amor pelo país nasce de experiências concretas, próximas e afetivas.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '32'), ('D12-TR-196-mb', 'Os temas associados são família, trabalho, comida, humor, amigos, cuidado, território e orgulho regional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '32'), ('D12-TR-198-mb', 'Isotopia de amor apesar das falhas: o vínculo com o Brasil se fortalece quando reconhece problemas sem abandonar o pertencimento.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '32'), ('D12-TR-199-mb', 'Os temas associados são patriotismo lúcido e crítica à violência, à corrupção, à desigualdade e a serviços públicos falhos, sem negar orgulho e afeto.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '32'), ('D12-TR-203-mb', 'A tensão central não é entre orgulho e vergonha do Brasil, mas entre desencanto com o país real e a possibilidade de se reencantar sem mentir.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '33'), ('D12-TR-204-mb', 'O Brasil aparece atravessado por falhas concretas: violência, corrupção, desigualdade, serviços públicos insuficientes, custo de vida e descrença institucional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '33'), ('D12-TR-206-mb', 'Busca-se uma forma crível de pertencimento: poder amar o Brasil sem negar seus problemas, reconhecer potência no país vivido e acreditar que algo ainda pode melhorar.', 'mulheres beneficiárias', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '33'), ('D12-TR-207-mb', 'O Brasil volta a encantar quando aparece como experiência concreta e compartilhada: povo, cultura, comida, humor, família, SUS, PIX, ciência, esporte, território, acolhimento e reconhecimento internacional.', 'mulheres beneficiárias', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '33');
